"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[34539],{49098:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"NpcHitFxController","desc":"Hit feedback for `EnemyNPC` models with attribute health (pirate boarders,\\nno Humanoid), plus the damage numbers of every enemy:\\n\\n- **Glow:** on every `Health` drop `HitFlash` flashes the body (everyone sees it).\\n- **Health bar:** `NpcHealthBar` on the Head, built on the first drop.\\n- **Damage numbers (every enemy):** `Packets.NpcDamaged` (server \u2192 the hitter only) \u2192\\n  `DamageNumbers.Show`: above the head for attribute bodies, at the hit point\\n  for Humanoid bodies (void enemies), and in the `far` style (fixed screen size)\\n  when the model does not replicate (the Leviathan). Hits within `MERGE_WINDOW`\\n  on one body add up into one number (a shotgun shot shows one number, not one per pellet).","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/NpcHitFxController.client.luau"}}')}}]);